         */
        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'UNSTRUCTURED-DATA-ANALYSIS-BASIC-V2'],
            [
                'module_no' => 20,
                'title' => 'Analysis of Unstructured Data',
                'year_level' => 'Year 4',
                'version_no' => 2,
                'version_name' => 'Analysis of Unstructured Data Practice and MCQ Review',
                'version_code' => 'V2',
                'description' => 'Text mining, NLP, sentiment analysis, image processing, web scraping, and feature extraction from raw data. This version emphasizes code tracing, worked practice, debugging, MCQ reasoning, comparison of methods, and mastery evidence.',
                'estimated_minutes' => 780,
                'sort_order' => 59,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'UNSTRUCTURED-DATA-ANALYSIS-BASIC-V2')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'UNSTRUCTURED-DATA-ANALYSIS-BASIC-V2')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);
